import heapq
from typing import List

class Solution:
    def shortestDistance(self, maze: List[List[int]], start: List[int], destination: List[int]) -> int:
        m, n = len(maze), len(maze[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[start[0]][start[1]] = 0
        pq = [(0, start[0], start[1])]
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while pq:
            d, r, c = heapq.heappop(pq)
            if d > dist[r][c]:
                continue
            if r == destination[0] and c == destination[1]:
                return d
            for dr, dc in dirs:
                nr, nc = r, c
                count = 0
                while 0 <= nr + dr < m and 0 <= nc + dc < n and maze[nr + dr][nc + dc] == 0:
                    nr += dr
                    nc += dc
                    count += 1
                if d + count < dist[nr][nc]:
                    dist[nr][nc] = d + count
                    heapq.heappush(pq, (d + count, nr, nc))

        return -1

class Solution {
public:
    int shortestDistance(vector<vector<int>>& maze, vector<int>& start, vector<int>& destination) {
        int m = maze.size(), n = maze[0].size();
        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
        dist[start[0]][start[1]] = 0;
        using Node = tuple<int, int, int>;
        priority_queue<Node, vector<Node>, greater<Node>> pq;
        pq.push({0, start[0], start[1]});
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.empty()) {
            auto [d, r, c] = pq.top();
            pq.pop();
            if (d > dist[r][c]) continue;
            if (r == destination[0] && c == destination[1]) return d;
            for (auto& dir : dirs) {
                int nr = r, nc = c, count = 0;
                while (nr + dir[0] >= 0 && nr + dir[0] < m && nc + dir[1] >= 0 && nc + dir[1] < n && maze[nr + dir[0]][nc + dir[1]] == 0) {
                    nr += dir[0];
                    nc += dir[1];
                    count++;
                }
                if (d + count < dist[nr][nc]) {
                    dist[nr][nc] = d + count;
                    pq.push({d + count, nr, nc});
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int shortestDistance(int[][] maze, int[] start, int[] destination) {
        int m = maze.length, n = maze[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) java.util.Arrays.fill(row, Integer.MAX_VALUE);
        dist[start[0]][start[1]] = 0;
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>(java.util.Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, start[0], start[1]});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], r = top[1], c = top[2];
            if (d > dist[r][c]) continue;
            if (r == destination[0] && c == destination[1]) return d;
            for (int[] dir : dirs) {
                int nr = r, nc = c, count = 0;
                while (nr + dir[0] >= 0 && nr + dir[0] < m && nc + dir[1] >= 0 && nc + dir[1] < n && maze[nr + dir[0]][nc + dir[1]] == 0) {
                    nr += dir[0];
                    nc += dir[1];
                    count++;
                }
                if (d + count < dist[nr][nc]) {
                    dist[nr][nc] = d + count;
                    pq.offer(new int[]{d + count, nr, nc});
                }
            }
        }
        return -1;
    }
}

